// Invariant Validator implementations
int LookupResult_int_IsValid(LookupResult_int* req) {
    if (req == NULL) return 0;
    if (req->Ok != 0x00 && req->Ok != 0x01) return 0;
    return 1;
}

int LookupResult_str_IsValid(LookupResult_str* req) {
    if (req == NULL) return 0;
    if (req->Ok != 0x00 && req->Ok != 0x01) return 0;
    return 1;
}

int lexer__StringHeader_IsValid(lexer__StringHeader* req) {
    if (req == NULL) return 0;
    return 1;
}

// Program Statements
void lexer__read_char(lexer__Lexer* l) {
    {
    if (((*(l)).ch == 10)) {
    (*(l)).line = ((*(l)).line + 1);
    (*(l)).column = 1;
    } else {
    if (((*(l)).position > 0)) {
    (*(l)).column = ((*(l)).column + 1);
    } else {
    if (((*(l)).position == 0)) {
    if (((*(l)).ch != 0)) {
    (*(l)).column = ((*(l)).column + 1);
    }
    }
    }
    }
    if (((*(l)).read_position >= (*(l)).input.len)) {
    (*(l)).ch = 0;
    } else {
    (*(l)).ch = std_str_byte_at((*(l)).input, (*(l)).read_position);
    }
    (*(l)).position = (*(l)).read_position;
    (*(l)).read_position = ((*(l)).read_position + 1);
    }
}

void* lexer__read_char_pthread_wrapper(void* arg) {
    lexer__read_char((lexer__Lexer*)arg);
    return NULL;
}

void lexer__init_lexer(lexer__Lexer* l, Slice_unsigned_char input) {
    {
    (*(l)).input = input;
    (*(l)).position = 0;
    (*(l)).read_position = 0;
    (*(l)).ch = 0;
    (*(l)).line = 1;
    (*(l)).column = 1;
    lexer__read_char(l);
    }
}

unsigned char lexer__peek_char(lexer__Lexer* l) {
    {
    if (((*(l)).read_position >= (*(l)).input.len)) {
    return 0;
    }
    return std_str_byte_at((*(l)).input, (*(l)).read_position);
    }
}

void* lexer__peek_char_pthread_wrapper(void* arg) {
    lexer__peek_char((lexer__Lexer*)arg);
    return NULL;
}

void lexer__skip_whitespace(lexer__Lexer* l) {
    {
    while (std_is_whitespace((*(l)).ch)) {
        if (GUST_UNLIKELY(--gust_loop_ticks <= 0)) { gust_loop_ticks = GUST_TICK_INTERVAL; gust_yield(); }
    lexer__read_char(l);
    }
    }
}

